'use client'
import { createMachine, useMachine, cn } from '@cascivo/core'
import { forwardRef } from 'react'
import type { CSSProperties, TextareaHTMLAttributes } from 'react'
import styles from './textarea.module.css'

const machine = createMachine({
  initial: 'idle' as const,
  states: {
    idle: { on: { FOCUS: 'focused' } },
    focused: { on: { BLUR: 'idle' } },
  },
})

export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  /**
   * Invisible accessible name, for when a visible element outside this component already
   * labels it (a heading in a settings row, a table column header) and `label` would render
   * that text a second time.
   *
   * `label` on this component is **visible** — it is painted next to the control. The catalog
   * splits that way deliberately, but `IconButton.label` and `Sparkline.label` are invisible
   * names, so an adopter arriving with that prior writes `label` here and gets the text twice
   * (2026-08-22 report item 13). Both props are now listed side by side, each saying which it
   * is, which is the only thing that interrupts a confident wrong guess.
   *
   * The raw DOM `aria-label` is still accepted and wins over this.
   */
  ariaLabel?: string
  label?: string
  hint?: string
  error?: string
  resize?: 'none' | 'vertical' | 'both'
  /**
   * Grow the control with its content instead of holding the fixed rows height. rows becomes
   * the minimum and --cascivo-textarea-max-block-size (default 20lh) the ceiling. Pure CSS
   * (field-sizing: content) — no measurement and no listener; where unsupported the fixed
   * rows height is kept.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  autosize?: boolean
  /**
   * AI presence: an AI-tinted border and a soft aura, marking a value AI produced or
   * suggested. Visual only — put an AiBadge in the label so the provenance is also text, and
   * clear `ai` once the person edits the value.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  ai?: boolean
}

/**
 * `forwardRef` so `ref` reaches the underlying `<textarea>` — and so it is TYPED.
 *
 * Under React 19 the ref already arrived at runtime (it is passed as an ordinary prop and
 * spread onto the element), but no component declared it, so `<Textarea ref={r} />` was a
 * `ts(2322)` and every consumer needing the element had to cast. One needed it for caret
 * restoration in a collaborative editor and kept the cast quarantined in its own file
 * (2026-07-28 report C10).
 *
 * `forwardRef` rather than adding `ref?: Ref<T>` to the props interface: the peer floor is
 * `react >= 18`, where ref-as-prop does NOT work — a bare type declaration would compile
 * and silently hand back `null` there. This keeps the floor honest on both majors, and
 * matches `IconButton`, which already used it.
 */
export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
  {
    label,
    hint,
    error,
    resize = 'vertical',
    autosize = false,
    ai = false,
    rows = 4,
    ariaLabel,
    className,
    id,
    onFocus,
    onBlur,
    ...props
  },
  ref,
) {
  const [state, send] = useMachine(machine)
  const textareaId =
    id ?? (label ? `cascade-textarea-${label.toLowerCase().replace(/\s+/g, '-')}` : undefined)

  return (
    <div
      className={cn(styles['wrapper'], className)}
      data-state={error ? 'error' : state.value}
      data-resize={resize}
      data-autosize={autosize ? '' : undefined}
      data-ai={ai ? '' : undefined}
      style={autosize ? ({ ['--_rows' as string]: String(rows) } as CSSProperties) : undefined}
    >
      {label && (
        <label className={styles['label']} htmlFor={textareaId}>
          {label}
        </label>
      )}
      <textarea
        ref={ref}
        id={textareaId}
        rows={rows}
        aria-multiline="true"
        className={styles['textarea']}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${textareaId}-error` : hint ? `${textareaId}-hint` : undefined}
        onFocus={(e) => {
          send('FOCUS')
          onFocus?.(e)
        }}
        onBlur={(e) => {
          send('BLUR')
          onBlur?.(e)
        }}
        {...props}
        aria-label={props['aria-label'] ?? ariaLabel}
      />
      {error && (
        <span id={`${textareaId}-error`} className={styles['error']} role="alert">
          {error}
        </span>
      )}
      {!error && hint && (
        <span id={`${textareaId}-hint`} className={styles['hint']}>
          {hint}
        </span>
      )}
    </div>
  )
})

@layer cascivo.component {
  .wrapper {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);

    &[data-resize='none'] .textarea {
      resize: none;
    }
    &[data-resize='vertical'] .textarea {
      resize: vertical;
    }
    &[data-resize='both'] .textarea {
      resize: both;
    }
  }

  /*
    Autosize. `rows` sets the height and nothing has ever grown it, so every adopter who
    wanted a comment box that follows its content re-implemented the `scrollHeight` dance —
    read the scroll height, write it back as an inline style, repeat on every keystroke, and
    get it wrong on paste and on font load.

    `field-sizing: content` is the platform's answer: the textarea sizes to what is typed.
    The floor and ceiling are not optional — without `min-block-size` an empty box collapses
    to a single line, and without `max-block-size` a pasted essay pushes the submit button
    off screen. The floor is exactly the `rows` height, so the control starts where it starts
    today and only ever grows.

    Progressive enhancement: where `field-sizing` is unsupported the declaration is dropped
    and `rows` governs, which is the current behaviour in full.
  */
  .wrapper[data-autosize] .textarea {
    /* `lh` is the computed line height of this very element, so N rows is literally
       `N * 1lh` — no re-deriving it from the font tokens, which drift. */
    /* `+ 2px` is the 1px border on each block edge — without it the floor lands 2px under
       the height the same `rows` produces without `autosize`, so turning the prop on nudged
       the layout. */
    min-block-size: calc(var(--_rows, 4) * 1lh + var(--cascivo-space-3) * 2 + 2px);
    max-block-size: var(--cascivo-textarea-max-block-size, 20lh);

    @supports (field-sizing: content) {
      field-sizing: content;
    }
  }

  .label {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
    line-height: var(--cascivo-leading-snug);
  }

  .textarea {
    width: 100%;
    min-block-size: 4rem;
    padding-inline: var(--cascivo-space-4);
    padding-block: var(--cascivo-space-3);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-normal);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-field);
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);
    outline: none;

    &::placeholder {
      color: var(--cascivo-color-text-muted);
    }

    /* AI presence — the value was produced or suggested by AI. Under :where() so hover,
       focus and the error state (all later or more specific) still win. */
    :where(.wrapper[data-ai]) & {
      border-color: var(--cascivo-color-ai-border);
      background-image: linear-gradient(to top, var(--cascivo-color-ai-subtle), transparent);
    }

    &:hover:not(:disabled):not(:focus) {
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus {
      border-color: var(--cascivo-color-accent);
      box-shadow: var(--cascivo-focus-ring);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
      background-color: var(--cascivo-color-bg-subtle);
    }

    .wrapper[data-state='error'] & {
      border-color: var(--cascivo-color-destructive);

      &:focus {
        box-shadow: 0 0 0 3px rgb(from var(--cascivo-color-destructive) r g b / 0.3);
      }
    }
  }

  .error {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-destructive);
    line-height: var(--cascivo-leading-snug);
  }

  .hint {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-snug);
  }

  /* Coarse-pointer touch targets — raise minimum to 44px, desktop density unchanged */
  @media (pointer: coarse) {
    .textarea {
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }
}

@media (forced-colors: active) {
  .textarea {
    border: 1px solid FieldText;
    color: FieldText;
    background-color: Field;
  }

  .textarea:focus {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}
